import { fromMarkdown } from 'mdast-util-from-markdown';
import { gfmFromMarkdown } from 'mdast-util-gfm';
import { mdxFromMarkdown } from 'mdast-util-mdx';
import { gfm } from 'micromark-extension-gfm';
import { mdxjs } from 'micromark-extension-mdxjs';
import { describe, expect, it } from 'vitest';
import { remarkMdxRemoveJs } from './remarkMdxRemoveJs.js';
function parse(mdx) {
    return fromMarkdown(mdx, {
        extensions: [gfm(), mdxjs()],
        mdastExtensions: [gfmFromMarkdown(), mdxFromMarkdown()],
    });
}
function extractText(node) {
    if (node.type === 'text' && typeof node.value === 'string') {
        return node.value;
    }
    if ('children' in node && Array.isArray(node.children)) {
        return node.children
            .map((child) => extractText(child))
            .join('');
    }
    return '';
}
function applyPlugin(mdx) {
    const tree = parse(mdx);
    remarkMdxRemoveJs()(tree);
    return tree;
}
describe('remarkMdxRemoveJs', () => {
    describe('expression removal (existing behaviour)', () => {
        it('removes arbitrary binary expressions', () => {
            const tree = applyPlugin('Sum is {1 + 1} here.');
            const text = extractText(tree);
            expect(text).not.toContain('1 + 1');
            expect(text).not.toContain('2');
            expect(text).toContain('Sum is');
            expect(text).toContain('here.');
        });
        it('removes function call expressions', () => {
            const tree = applyPlugin('Items: {["a","b"].map(x => x)} end.');
            const text = extractText(tree);
            expect(text).not.toContain('map');
            expect(text).toContain('Items:');
            expect(text).toContain('end.');
        });
        it('removes template literals', () => {
            const tree = applyPlugin('Val {`tpl-${1 + 1}`} end.');
            const text = extractText(tree);
            expect(text).not.toContain('tpl');
            expect(text).toContain('Val');
            expect(text).toContain('end.');
        });
    });
    describe('string constant substitution (new behaviour)', () => {
        it('substitutes a bare identifier that maps to an exported string constant', () => {
            const mdx = `export const versions = "v1.2.3 and later";

On {versions}, this feature requires opt-in.`;
            const tree = applyPlugin(mdx);
            const text = extractText(tree);
            expect(text).toContain('v1.2.3 and later');
            expect(text).toContain('On v1.2.3 and later, this feature requires opt-in.');
        });
        it('substitutes a page-level export const used inline', () => {
            const mdx = `export const ver = "v5.5.5-CONSTVAL";

Version {ver} here.`;
            const tree = applyPlugin(mdx);
            expect(extractText(tree)).toContain('Version v5.5.5-CONSTVAL here.');
        });
        it('substitutes multiple constants from separate export statements', () => {
            const mdx = `export const a = "AAA";
export const b = "BBB";

{a} and {b}.`;
            const tree = applyPlugin(mdx);
            const text = extractText(tree);
            expect(text).toContain('AAA');
            expect(text).toContain('BBB');
        });
        it('substitutes all declarators in a multi-declarator const', () => {
            const mdx = `export const a = "AAA", b = "BBB";

{a} and {b}.`;
            const tree = applyPlugin(mdx);
            const text = extractText(tree);
            expect(text).toContain('AAA');
            expect(text).toContain('BBB');
        });
        it('does not substitute non-string (number) constants', () => {
            const mdx = `export const count = 42;

Value {count} here.`;
            const tree = applyPlugin(mdx);
            const text = extractText(tree);
            expect(text).not.toContain('42');
            expect(text).toContain('Value');
            expect(text).toContain('here.');
        });
        it('does not substitute identifiers with no matching export', () => {
            const tree = applyPlugin('Value {unknown} here.');
            const text = extractText(tree);
            expect(text).not.toContain('unknown');
            expect(text).toContain('Value');
            expect(text).toContain('here.');
        });
        it('substitutes the constant but still removes unresolvable expressions in the same page', () => {
            const mdx = `export const x = "hello";

Result {1 + 1} and {x} here.`;
            const tree = applyPlugin(mdx);
            const text = extractText(tree);
            expect(text).toContain('hello');
            expect(text).not.toContain('1 + 1');
            expect(text).toContain('Result');
            expect(text).toContain('and hello here.');
        });
    });
});
